import {applyTenantTheme} from './tenant-theme.mjs';
import {lifecycleText} from './family-admin.mjs';
import {tenantBilling,showPlans,showInvoices} from './platform-billing.mjs';
import {tenantOperations} from './tenant-operations.mjs';
import {subscriptionAdmin} from './subscriptions.mjs';
import {Capacitor} from './capacitor-core.mjs';
import {syncFamilyIcons} from './family-icons.mjs';
export function initTenants({state,req,element,button,busy,toast,start,logout,saveSession}){
 let selected=null,searchVersion=0;try{selected=JSON.parse(localStorage.getItem('family-selection')||'null')}catch{}
 const rpc=(name,body={},auth=true)=>req('/rest/v1/rpc/'+name,{method:'POST',body,auth});
 const screen=element('section',undefined,'tenant-entry');screen.id='tenant-entry';screen.hidden=true;
 const box=element('div',undefined,'tenant-entry-card');const platformMark=element('img');platformMark.src='/platform-logo.png';platformMark.alt='منصة العوائل';platformMark.className='platform-entry-mark';box.append(platformMark);box.append(element('h1','أهلًا بك'),element('p','اختر عائلتك مرة واحدة، أو اطلب إنشاء كيان جديد.'));
 const search=element('input');search.id='tenant-code';search.placeholder='كود العائلة أو اسمها';search.maxLength=80;search.setAttribute('aria-label','كود العائلة أو اسمها');const results=element('div');results.id='tenant-results';const status=element('p');status.setAttribute('role','status');
 const form=element('form');form.id='tenant-request';form.innerHTML='<h2>تسجيل عائلة جديدة</h2><label>اسم العائلة<input name="name" minlength="3" maxlength="100" required></label><label>رقم التواصل<input name="phone" type="tel" placeholder="+9665…" required></label><label>البريد الإلكتروني<input name="email" type="email" required maxlength="254"></label><label>شعار العائلة<input name="logo" type="file" accept="image/*"></label><button class="primary">بدء التجربة المجانية</button><p>تجربة مجانية 30 يومًا دون انتظار التفعيل. بعدها يتوقف الإضافة والدردشة؛ وبعد 30 يومًا إضافية دون اشتراك يحذف الكيان وصوره وبياناته نهائيًا. تأكيد بريد المدير مطلوب.</p>';
 const dropdown=element('details',undefined,'tenant-dropdown');dropdown.open=true;const summary=element('summary','اختر من العوائل المتاحة');dropdown.append(summary,results);box.append(search,dropdown,status,button('تسجيل عائلة جديدة',()=>{form.hidden=!form.hidden},'secondary'),form);form.hidden=true;box.append(button('دخول إدارة المنصة',platformLogin,'text-button'));screen.append(box);document.body.append(screen);
 function brand(){applyTenantTheme(selected);syncFamilyIcons(selected);const name=selected?.name||'منصة العوائل';document.title=name;for(const img of document.querySelectorAll('img.brand-logo,.brand img,.launch-orbit img'))if(/logo/i.test(img.className+' '+(img.getAttribute('src')||''))||img.alt==='أخبار العائلة'){if(!img.dataset.defaultLogo)img.dataset.defaultLogo=img.getAttribute('src');img.src=selected?.logo||(selected?.code==='01'?'/family-logo.png':'/platform-logo.png');img.alt=name}const label=document.querySelector('.brand>span');if(label?.firstChild)label.firstChild.textContent=name;const footer=document.querySelector('footer');if(footer?.firstChild)footer.firstChild.textContent='✦ '+name+' ';const orbit=document.querySelector('.launch-orbit img');if(orbit){if(!orbit.dataset.defaultLogo)orbit.dataset.defaultLogo=orbit.src;orbit.src=selected?.logo||(selected?.code==='01'?'/family-01-icon-512.png':'/icon-512.png');}for(const el of document.querySelectorAll('.tenant-name'))el.textContent=name;}
 function persist(t){selected=t;localStorage.setItem('family-selection',JSON.stringify(t));brand()}
 async function choose(t){if(state.session&&selected?.id!==t.id)await logout();persist(t);screen.hidden=true;document.getElementById('auth-screen').hidden=!!state.user;if(state.session)await start();document.dispatchEvent(new CustomEvent('family:tenant-selected'));}
 async function searchFamilies(){const version=++searchVersion;status.textContent='جاري البحث…';try{const rows=await rpc('tenant_directory',{term:search.value.trim()},false);if(version!==searchVersion)return;results.replaceChildren();for(const t of rows){const b=button('',()=>{const d=element('dialog',undefined,'tenant-confirm');d.append(element('h2',t.name),element('p','الدخول إلى كيان العائلة '+t.code+' وحفظه على هذا الجهاز؟'),element('p',familyBrandNotice(t)),button('تأكيد الدخول',async()=>{d.close();d.remove();await choose(t)},'primary'),button('إلغاء',()=>{d.close();d.remove()}));document.body.append(d);d.showModal()});{const i=element('img');i.src=t.logo||(t.code==='01'?'/family-01-icon-192.png':'/platform-logo.png');i.alt='شعار '+t.name;b.append(i)}b.append(element('strong',t.name),element('small','الكود '+t.code));results.append(b)}status.textContent=rows.length?'':'لا توجد عائلة مفعّلة مطابقة.';}catch(e){status.textContent=e.message}}
 function familyBrandNotice(t){const base='ستظهر واجهة '+t.name+' باسمها وشعارها في كل مرة. ';if(Capacitor.getPlatform()==='android')return base+(t.code==='01'?'ستتغير أيقونة التطبيق واسمه على الشاشة الرئيسية إلى أخبار العائلة.':'تغيير أيقونة الشاشة الرئيسية واسمها لهذا الكيان يتطلب تحديثًا يتضمن هويته.');if(Capacitor.getPlatform()==='ios'||/iPad|iPhone|iPod/.test(navigator.userAgent))return base+(t.code==='01'?'في نسخة الآيفون الأصلية ستتغير الأيقونة إلى شعار العائلة، ويبقى اسم التطبيق العوائل وفق قيود iOS.':'تغيير الأيقونة في نسخة الآيفون يتطلب تضمين شعار الكيان في تحديث؛ ويبقى اسم التطبيق العوائل.');return base+'عند إضافة التطبيق إلى الشاشة الرئيسية بعد الاختيار، يستخدم اسم العائلة وشعارها. النسخة المثبتة سابقًا قد تحتاج إعادة الإضافة.';}
 let debounce;search.oninput=()=>{dropdown.open=true;clearTimeout(debounce);debounce=setTimeout(searchFamilies,220)};
 async function logo(file){if(!file||file.size>20*1024*1024)throw Error('اختر شعارًا أقل من 20 ميجابايت.');const img=new Image(),url=URL.createObjectURL(file);try{img.src=url;await img.decode();const c=document.createElement('canvas'),scale=Math.min(1,512/Math.max(img.naturalWidth,img.naturalHeight));c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const encoded=c.toDataURL('image/jpeg',.72);if(encoded.length>280000)throw Error('اختر شعارًا أبسط أو أصغر.');return encoded}finally{URL.revokeObjectURL(url)}}
 form.onsubmit=e=>{e.preventDefault();return busy(e.submitter,async()=>{const f=form.elements;const message=await rpc('tenant_request',{data:{name:f.name.value.trim(),phone:f.phone.value.trim().replace(/^05/,'+9665'),email:f.email.value.trim(),logo:f.logo.files[0]?await logo(f.logo.files[0]):null}},false);form.reset();status.textContent=message;form.hidden=true})};
 const exit=button('الخروج من الكيان العائلي',async()=>{await logout();localStorage.removeItem('family-selection');state.readOnly=false;document.body.classList.remove('tenant-read-only');const banner=document.getElementById('readonly-banner');if(banner)banner.hidden=true;selected=null;brand();screen.hidden=false;document.getElementById('auth-screen').hidden=true;await searchFamilies()},'text-button danger');exit.id='tenant-exit';document.querySelector('.app-nav').append(exit);
 const change=button('تغيير الكيان العائلي',()=>exit.click(),'text-button');change.id='tenant-change';document.getElementById('auth-screen').append(change);
 let platformSession=null;
 async function adminRpc(name,body={}){if(!platformSession)throw Error('سجل الدخول إلى الإدارة.');if(platformSession.expires_at*1000<Date.now()+30000){const fresh=await req('/auth/v1/token?grant_type=refresh_token',{method:'POST',auth:false,body:{refresh_token:platformSession.refresh_token}});platformSession={...fresh,expires_at:Math.floor(Date.now()/1000)+(fresh.expires_in||3600)}}return req('/rest/v1/rpc/'+name,{method:'POST',body,auth:false,headers:{Authorization:'Bearer '+platformSession.access_token}})}
 async function platformLogin(){const d=element('dialog',undefined,'platform-login');const f=element('form');f.innerHTML='<h2>إدارة المنصة</h2><p>استخدم كلمة مرور حساب المالك المتحقق منه.</p><label>اسم الدخول أو البريد<input name="username" value="admin" autocomplete="username" required></label><label>كلمة المرور<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">دخول الإدارة</button>';
 const message=element('p');message.setAttribute('role','status');f.append(message);d.append(f,button('إغلاق',()=>{d.close();d.remove()}));document.body.append(d);d.showModal();f.onsubmit=e=>{e.preventDefault();return busy(e.submitter,async()=>{try{const email=f.elements.username.value.trim().toLowerCase()==='admin'?'martadha3li@gmail.com':f.elements.username.value.trim();const session=await req('/auth/v1/token?grant_type=password',{method:'POST',auth:false,body:{email,password:f.elements.password.value}});platformSession={...session,expires_at:Math.floor(Date.now()/1000)+(session.expires_in||3600)};await adminRpc('platform_action',{action:'check'});f.elements.password.value='';d.close();d.remove();await platform()}catch(error){message.textContent=error.message}})};}
 async function check(){}
 async function platform(){const rpc=adminRpc;const d=element('dialog',undefined,'platform-console');d.append(element('h2','إدارة المنصة'),element('p','تُسجّل الرسوم والسداد يدويًا. التفعيل بعد السداد أو الإعفاء. لا توجد بوابة دفع مفعّلة.'),button('خروج من الإدارة',()=>{platformSession=null;d.close();d.remove()}));const list=element('div'),nav=element('nav',undefined,'billing-tabs');nav.append(button('الكيانات',()=>load()),button('الباقات والاشتراكات',()=>showPlans({container:list,element,button,busy,rpc,toast})),button('الفواتير',()=>showInvoices({container:list,element,button,busy,rpc})),button('المهل والبريد والحذف',()=>busy(null,async()=>{const s=await rpc('platform_lifecycle',{action:'status'});list.replaceChildren(element('h3','المهل والبريد والحذف التلقائي'),element('p',s.schedule_active?'الفحص التلقائي يعمل كل ساعة.':'الفحص التلقائي غير مفعل.'),element('p','رسائل بانتظار الإرسال: '+s.pending_mail),element('p','حذف الاشتراكات المنتهية لا يبدأ إلا بعد إرسال بريد التجديد بنجاح ثم مرور 15 يومًا.'));for(const m of s.mail_errors)list.append(element('p',m.family+' · تعذّر إرسال البريد: '+m.error));for(const j of s.deletions)list.append(element('p',j.family+' · '+j.phase+' · '+(j.last_error||'')))})));d.append(nav,list);d.addEventListener('close',()=>{platformSession=null});document.body.append(d);d.showModal();async function load(){const [rows,plans]=await Promise.all([rpc('platform_action',{action:'list'}),rpc('platform_action',{action:'plans'})]);list.replaceChildren();for(const t of rows){const f=element('form',undefined,'tenant-admin-card');f.append(element('h3',t.name),element('p',t.contact_email+' · '+t.contact_phone),element('small',t.members+' عضو · '+t.posts+' خبر'));function field(key,label,type='text'){const l=element('label',label),i=element('input');i.name=key;i.type=type;i.value=t[key]??'';l.append(i);f.append(l);return i}field('name','اسم العائلة').required=true;field('code','كود العائلة').required=true;field('contact_email','بريد مدير الكيان','email');field('contact_phone','جوال مدير الكيان','tel');function select(key,label,opts){const l=element('label',label),i=element('select');i.name=key;for(const[v,label]of opts){const o=element('option',label);o.value=v;i.append(o)}i.value=t[key];l.append(i);f.append(l)}select('payment_status','السداد',[['unpaid','غير مسدد'],['paid','مسدد'],['waived','معفى']]);select('status','حالة الكيان',[['pending','بانتظار التفعيل'],['active','مفعّل'],['suspended','موقوف'],['rejected','مرفوض']]);field('notes','ملاحظات الإدارة');const save=element('button','حفظ','primary');f.append(save);f.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{const data=Object.fromEntries(new FormData(f));data.id=t.id;await rpc('platform_action',{action:'save',data});toast('حُفظت إعدادات الكيان.');await load()})};const card=element('article',undefined,'tenant-management');const lifecycle=element('p',lifecycleText({...t,trial:!!t.trial_ends_at&&t.payment_status==='unpaid',read_only:t.payment_status!=='waived'&&Date.parse(t.payment_status==='unpaid'&&t.trial_ends_at?t.trial_ends_at:t.subscription_ends_at)<Date.now(),delete_after:t.payment_status==='unpaid'&&t.trial_ends_at?new Date(Date.parse(t.trial_ends_at)+30*86400000).toISOString():t.renewal_notice_sent_at?new Date(Date.parse(t.renewal_notice_sent_at)+15*86400000).toISOString():null}),'lifecycle-notice');card.append(lifecycle);if(t.payment_status==='unpaid'&&!t.trial_started_at&&!t.subscription_ends_at)card.append(button('منح تجربة مجانية 30 يومًا',()=>busy(null,async()=>{if(!confirm('تجربة مجانية 30 يومًا؛ ثم 30 يومًا للاطلاع قبل الحذف النهائي دون اشتراك؟'))return;await rpc('platform_lifecycle',{action:'trial_start',payload:{id:t.id}});await load()}),'secondary'));card.append(f,tenantBilling({t,plans,element,button,busy,rpc,toast,reload:load}),tenantOperations({t,element,button,busy,rpc,toast,reload:load}));list.append(card)}}await load()}
 async function validate(){const current=await rpc('tenant_current');if(!current||current.status!=='active'){await logout();throw Error('الكيان غير متاح. تواصل مع إدارة المنصة.');}if(selected&&current.id!==selected.id){await logout();throw Error('هذا الحساب مسجل في كيان عائلي آخر. غيّر الكيان ثم سجّل الدخول.')}state.readOnly=!!current.read_only;document.body.classList.toggle("tenant-read-only",state.readOnly);let banner=document.getElementById("readonly-banner");if(!banner){banner=element("p",undefined,"readonly-banner");banner.id="readonly-banner";document.querySelector("header").after(banner)}banner.textContent=lifecycleText(current);banner.hidden=!(state.readOnly||current.trial);persist(current);return current}
 const accessTimer=setInterval(()=>{if(state.user&&state.session&&!document.hidden)validate().catch(e=>toast(e.message))},30000);accessTimer.unref?.();
 async function boot(){brand();if(new URLSearchParams(location.search).get('platform')==='1'){document.body.classList.add('platform-mode');screen.hidden=false;document.getElementById('auth-screen').hidden=true;platformLogin();return false}if(!selected){screen.hidden=false;document.getElementById('auth-screen').hidden=true;await searchFamilies();return false}return true}
 return {boot,validate,check,get selected(){return selected},brand};
}
